// FUNCIONES DE INFERENCIA
// ============================================================================

inline float silu(float x) {
    return x / (1.0f + expf(-x));
}

inline float clamp(float x, float lo, float hi) {
    return x < lo ? lo : (x > hi ? hi : x);
}

// Calcula B-splines cúbicos para un valor x
void compute_bsplines(float x, float* bases, int n_bases) {
    x = clamp(x, -2.5f, 2.5f);
    
    // Inicializar bases de orden 0
    float b0[GRID_POINTS-1];
    for (int j = 0; j < GRID_POINTS-1; j++) {
        b0[j] = (x >= GRID[j] && x < GRID[j+1]) ? 1.0f : 0.0f;
    }
    
    // Recursión Cox-de Boor para splines cúbicos
    float b1[GRID_POINTS-2], b2[GRID_POINTS-3], b3[GRID_POINTS-4];
    
    // Orden 1
    for (int j = 0; j < GRID_POINTS-2; j++) {
        float d1 = GRID[j+1] - GRID[j];
        float d2 = GRID[j+2] - GRID[j+1];
        d1 = (d1 == 0) ? 1.0f : d1;
        d2 = (d2 == 0) ? 1.0f : d2;
        b1[j] = (x - GRID[j]) / d1 * b0[j] + (GRID[j+2] - x) / d2 * b0[j+1];
    }
    
    // Orden 2
    for (int j = 0; j < GRID_POINTS-3; j++) {
        float d1 = GRID[j+2] - GRID[j];
        float d2 = GRID[j+3] - GRID[j+1];
        d1 = (d1 == 0) ? 1.0f : d1;
        d2 = (d2 == 0) ? 1.0f : d2;
        b2[j] = (x - GRID[j]) / d1 * b1[j] + (GRID[j+3] - x) / d2 * b1[j+1];
    }
    
    // Orden 3 (cúbico)
    for (int j = 0; j < n_bases; j++) {
        float d1 = GRID[j+3] - GRID[j];
        float d2 = GRID[j+4] - GRID[j+1];
        d1 = (d1 == 0) ? 1.0f : d1;
        d2 = (d2 == 0) ? 1.0f : d2;
        bases[j] = (x - GRID[j]) / d1 * b2[j] + (GRID[j+4] - x) / d2 * b2[j+1];
    }
}

// Capa KAN genérica
void kan_layer(const float* input, float* output, 
               const float* base_w, const float* base_b,
               const float* spline_w,
               int in_dim, int out_dim, int n_splines) {
    
    float bases[32];  // Max splines per input
    
    for (int o = 0; o < out_dim; o++) {
        // Base lineal con SiLU
        float sum = base_b[o];
        for (int i = 0; i < in_dim; i++) {
            sum += base_w[o * in_dim + i] * silu(input[i]);
        }
        
        // Spline contribution
        for (int i = 0; i < in_dim; i++) {
            compute_bsplines(input[i], bases, n_splines);
            for (int s = 0; s < n_splines; s++) {
                sum += spline_w[(o * in_dim + i) * n_splines + s] * bases[s];
            }
        }
        
        output[o] = sum;
    }
}

// ============================================================================
// FUNCIÓN PRINCIPAL: Predice posición y desde (u, i, phi)
// ============================================================================
float predict_position(float u, float i_current, float phi) {
    // 1. Normalizar entrada
    float input[3];
    input[0] = (u - U_MEAN) / U_STD;
    input[1] = (i_current - I_MEAN) / I_STD;
    input[2] = (phi - PHI_MEAN) / PHI_STD;
    
    // 2. Capa 1: [3] -> [32]
    float h1[32];
    kan_layer(input, h1, KAN1_BASE_W, KAN1_BASE_B, KAN1_SPLINE, 3, 32, GRID_SIZE + SPLINE_K);
    
    // 3. Capa 2: [32] -> [16]
    float h2[16];
    kan_layer(h1, h2, KAN2_BASE_W, KAN2_BASE_B, KAN2_SPLINE, 32, 16, GRID_SIZE + SPLINE_K);
    
    // 4. Capa 3: [16] -> [1]
    float out[1];
    kan_layer(h2, out, KAN3_BASE_W, KAN3_BASE_B, KAN3_SPLINE, 16, 1, GRID_SIZE + SPLINE_K);
    
    // 5. Desnormalizar salida
    float y = out[0] * Y_STD + Y_MEAN;
    
    // 6. Clamp a rango físico [2mm, 15mm]
    return clamp(y, 0.002f, 0.015f);
}

